import{_ as a,o as r,c as t,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"CRUSH-ing the OSD Variance Problem - Tom Byrne, Storage Sysadmin","description":"","frontmatter":{"title":"CRUSH-ing the OSD Variance Problem - Tom Byrne, Storage Sysadmin","date":"2019-05-24T00:00:00.000Z","updated":"2019-05-24T00:00:00.000Z","tags":["Ceph","分布式存储","OSD利用率管理","CRUSH算法","upmap balancer","群集平衡","数据分布","高可用性","可扩展性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/CRUSH-ing_the_OSD_Variance_Problem_-_Tom_Byrne_Storage_Sysadmin.md","filePath":"posts/2019/CRUSH-ing_the_OSD_Variance_Problem_-_Tom_Byrne_Storage_Sysadmin.md","lastUpdated":1780459816000}'),o={name:"posts/2019/CRUSH-ing_the_OSD_Variance_Problem_-_Tom_Byrne_Storage_Sysadmin.md"};function n(i,e,p,_,s,S){return r(),t("div",null,[...e[0]||(e[0]=[l("<p>Tom Byrne，Rutherford 下午实验室的系统管理员，在会议中讨论了Ceph分布式存储系统中OSD利用率管理的问题。以下是会议的关键点：</p><p><strong>会议背景</strong>：</p><ul><li>Tom在Rutherford下午实验室负责与研究人员合作存储数据，自2015年开始关注Ceph，主要关注高性能物理实验的对象存储。</li><li>Echo是他们运行的最大的高性能计算集群，已投入生产两年，目前容量超过40PB，主要服务于大型实验设施。</li></ul><p><strong>OSD利用率管理</strong>：</p><ul><li>Echo集群中OSD利用率存在较大差异，导致空间浪费和数据分布不均。</li><li>初始方案使用reweight by utilization尝试平衡OSD利用率，但效果不佳。</li><li>改进方案引入upmap balancer，通过强制移动placement groups到空置或利用率较低的OSD，有效平衡了集群利用率，并将利用率差异从40%降低到5%，增加了6PB的额外可用空间。</li><li>upmap balancer的优势包括更高效地平衡集群利用率、更灵活地控制placement groups的分布、提高集群的可用性和可靠性。</li></ul><p><strong>添加OSD</strong>：</p><ul><li>添加OSD时需要逐步增加权重，并监控集群状态。</li><li>添加新OSD时，可能存在placement groups在现有OSD之间移动的情况，导致数据分布不均。</li><li>解决方案包括使用upmap map将placement groups移动到新OSD，使用工具监控placement groups的移动情况，确保数据分布均匀。</li></ul><p><strong>结论</strong>：</p><ul><li>Tom强调了upmap balancer在平衡Ceph集群利用率方面的重要性，并分享了添加OSD的经验和挑战。</li><li>后续行动计划包括继续使用upmap balancer平衡Echo集群的利用率，持续监控集群状态，确保数据分布均匀，评估添加更多OSD的可行性。</li></ul><p><strong>改进点</strong>：</p><ul><li>原始总结中未提及Echo集群的规模和重要性，以及upmap balancer的具体作用。</li><li>改进后的总结更详细地描述了OSD利用率管理和添加OSD的过程，并强调了upmap balancer的优势。</li><li>保留了计算机科学/ceph相关领域的英文原文关键词。</li></ul>",11)])])}const u=a(o,[["render",n]]);export{c as __pageData,u as default};
